            g.Field(x => x.F16Choice, f => f.DisplayName("Choice 79.16").AllowedValue("a", "a", "Alpha").AllowedValue("b", "b", "Bravo").AllowedValue("c", "c", "Charlie").AllowedValue("d", "d", "Delta").AllowedValue("e", "e", "Echo"));
            g.Field(x => x.F17Tags, f => f.DisplayName("Tags 79.17").AllowedElementValue<string>("red", "red", "Red").AllowedElementValue<string>("green", "green", "Green").AllowedElementValue<string>("blue", "blue", "Blue").AllowedElementValue<string>("amber", "amber", "Amber"));
            g.Field(x => x.F18Code, f => f.DisplayName("Code 79.18").Pattern("[A-Z]{3}-[0-9]{3}"));
            g.Field(x => x.F19Percent, f => f.DisplayName("Percent 79.19").Range(0m, 100m));
            g.Field(x => x.F20Note, f => f.DisplayName("Note 79.20").MaxLength(500).Annotate("ui:control", "textarea"));
            g.Field(x => x.F21Text, f => f.DisplayName("Text 79.21").MaxLength(80));
            g.Field(x => x.F22Count, f => f.DisplayName("Count 79.22").Range(0, 10000).Validation(p => p.For<LargeFormSubmitProfile>(r => r.Required())));
            g.Field(x => x.F23Amount, f => f.DisplayName("Amount 79.23").Min(0m));
            g.Field(x => x.F24Flag, f => f.DisplayName("Flag 79.24").Default(false));
            g.Field(x => x.F25Date, f => f.DisplayName("Date 79.25").Max(new DateOnly(2099, 12, 31)));
        }, o => o.DisplayName("Section 79"));
        builder.FieldGroup(x => x.S080, g =>
        {
            g.Field(x => x.F01Count, f => f.DisplayName("Count 80.1").Range(0, 10000));
            g.Field(x => x.F02Amount, f => f.DisplayName("Amount 80.2").Min(0m));
            g.Field(x => x.F03Flag, f => f.DisplayName("Flag 80.3").Default(false));
            g.Field(x => x.F04Date, f => f.DisplayName("Date 80.4").Max(new DateOnly(2099, 12, 31)));
            g.Field(x => x.F05Choice, f => f.DisplayName("Choice 80.5").AllowedValue("a", "a", "Alpha").AllowedValue("b", "b", "Bravo").AllowedValue("c", "c", "Charlie").AllowedValue("d", "d", "Delta").AllowedValue("e", "e", "Echo").Validation(p => p.For<LargeFormSubmitProfile>(r => r.Required())));
            g.Field(x => x.F06Tags, f => f.DisplayName("Tags 80.6").AllowedElementValue<string>("red", "red", "Red").AllowedElementValue<string>("green", "green", "Green").AllowedElementValue<string>("blue", "blue", "Blue").AllowedElementValue<string>("amber", "amber", "Amber"));
            g.Field(x => x.F07Code, f => f.DisplayName("Code 80.7").Pattern("[A-Z]{3}-[0-9]{3}"));
            g.Field(x => x.F08Percent, f => f.DisplayName("Percent 80.8").Range(0m, 100m));
            g.Field(x => x.F09Note, f => f.DisplayName("Note 80.9").MaxLength(500).Annotate("ui:control", "textarea"));
            g.Field(x => x.F10Text, f => f.DisplayName("Text 80.10").MaxLength(80));
            g.Field(x => x.F11Count, f => f.DisplayName("Count 80.11").Range(0, 10000));
            g.Field(x => x.F12Amount, f => f.DisplayName("Amount 80.12").Min(0m).Validation(p => p.For<LargeFormSubmitProfile>(r => r.Required())));
            g.Field(x => x.F13Flag, f => f.DisplayName("Flag 80.13").Default(false));
            g.Field(x => x.F14Date, f => f.DisplayName("Date 80.14").Max(new DateOnly(2099, 12, 31)));
            g.Field(x => x.F15Choice, f => f.DisplayName("Choice 80.15").AllowedValue("a", "a", "Alpha").AllowedValue("b", "b", "Bravo").AllowedValue("c", "c", "Charlie").AllowedValue("d", "d", "Delta").AllowedValue("e", "e", "Echo"));
            g.Field(x => x.F16Tags, f => f.DisplayName("Tags 80.16").AllowedElementValue<string>("red", "red", "Red").AllowedElementValue<string>("green", "green", "Green").AllowedElementValue<string>("blue", "blue", "Blue").AllowedElementValue<string>("amber", "amber", "Amber"));
            g.Field(x => x.F17Code, f => f.DisplayName("Code 80.17").Pattern("[A-Z]{3}-[0-9]{3}"));
            g.Field(x => x.F18Percent, f => f.DisplayName("Percent 80.18").Range(0m, 100m));
            g.Field(x => x.F19Note, f => f.DisplayName("Note 80.19").MaxLength(500).Annotate("ui:control", "textarea"));
            g.Field(x => x.F20Text, f => f.DisplayName("Text 80.20").MaxLength(80));
            g.Field(x => x.F21Count, f => f.DisplayName("Count 80.21").Range(0, 10000));
            g.Field(x => x.F22Amount, f => f.DisplayName("Amount 80.22").Min(0m));
            g.Field(x => x.F23Flag, f => f.DisplayName("Flag 80.23").Default(false));
            g.Field(x => x.F24Date, f => f.DisplayName("Date 80.24").Max(new DateOnly(2099, 12, 31)));
            g.Field(x => x.F25Choice, f => f.DisplayName("Choice 80.25").AllowedValue("a", "a", "Alpha").AllowedValue("b", "b", "Bravo").AllowedValue("c", "c", "Charlie").AllowedValue("d", "d", "Delta").AllowedValue("e", "e", "Echo"));
        }, o => o.DisplayName("Section 80").Resettable());
        builder.Collection(x => x.Lines, lines =>
        {
            lines.DisplayName("Lines");
            lines.Item<LargeForm2000Line>("LINE", line =>
            {
                line.Field(x => x.Description, f => f.DisplayName("Description").MaxLength(200).Annotate("ui:title", true));
                line.Field(x => x.Quantity, f => f.DisplayName("Quantity").Range(0, 100000).Default(1));
                line.Field(x => x.UnitPrice, f => f.DisplayName("Unit Price").Min(0m));
                line.Field(x => x.Amount, f => f.DisplayName("Amount").Min(0m));
                line.Field(x => x.Category, f => f.DisplayName("Category").AllowedValue("goods", "goods", "Goods").AllowedValue("services", "services", "Services").AllowedValue("fees", "fees", "Fees"));
                line.Field(x => x.Taxable, f => f.DisplayName("Taxable").Default(true));
                line.Field(x => x.ServiceDate, f => f.DisplayName("Service Date"));
                line.Field(x => x.Reference, f => f.DisplayName("Reference").Pattern("[A-Z]{3}-[0-9]{3}"));
                line.Field(x => x.DiscountPercent, f => f.DisplayName("Discount %").Range(0m, 100m));
                line.Field(x => x.Notes, f => f.DisplayName("Notes").MaxLength(500).Annotate("ui:control", "textarea"));
            });
            lines.MaxCount(1000);
            lines.AggregateSum("Amount").LessThanOrEqual(1_000_000_000m);
        });
        builder.NestedNode(x => x.Party, party => party
            .DisplayName("Party")
            .Bind<LargeForm2000Person>("PERSON", p => { p.Field(x => x.FullName, f => f.DisplayName("Full Name")); p.Field(x => x.BirthDate, f => f.DisplayName("Birth Date")); })
            .Bind<LargeForm2000Organization>("ORGANIZATION", o => { o.Field(x => x.LegalName, f => f.DisplayName("Legal Name")); o.Field(x => x.TaxId, f => f.DisplayName("Tax Id").Pattern("[A-Z]{2}[0-9]{8}")); })
            .DefaultType<LargeForm2000Organization>());
        builder.Operation("SUBMIT", x => x.Submit);
        builder.OnChange(path => path.Collection(x => x.Lines).Field(x => x.Amount), x => x.RecalculateLines);
        builder.OnChange(path => path.Collection(x => x.Lines).Any(), x => x.RecalculateLines);
        return builder.Build();
    }
}
